import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private SettingsHolder settingsHolder;

    @Test
    public void newCommentConfigurationCreation_ReturnsInstance() {
        CommentsConfiguration commentConfiguration = new CommentsConfiguration();
        Mockito.when(settingsHolder.getComments()).thenReturn(Collections.emptyMap());
        assertNotNull(commentConfiguration);
    }

    @Test
    public void newCommentConfigurationCreationFromMap_ReturnsInstance() {
        Map<String, List<String>> comments = Collections.singletonMap("key", Arrays.asList("value"));
        CommentsConfiguration commentConfiguration = new CommentsConfiguration(comments);
        assertNotNull(commentConfiguration);
    }

    @Test
    public void setComment_AddsLinesForProvidedPath() {
        String path = "path";
        String[] commentLines = {"line1", "line2"};
        CommentsConfiguration commentConfiguration = new CommentsConfiguration();
        commentConfiguration.setComment(path, commentLines);
        List<String> expectedCommentLines = Arrays.asList("line1", "line2");
        Mockito.when(settingsHolder.getComments()).thenReturn(Collections.emptyMap());
        assertEquals(expectedCommentLines, commentConfiguration.getAllComments().get(path));
    }

    @Test
    public void setComment_AddsEmptyLineForNewEntry() {
        String path = "path";
        String[] commentLines = {"line1", "", "line3"};
        CommentsConfiguration commentConfiguration = new CommentsConfiguration();
        commentConfiguration.setComment(path, commentLines);
        List<String> expectedCommentLines = Arrays.asList("line1", "", "line3");
        Mockito.when(settingsHolder.getComments()).thenReturn(Collections.emptyMap());
        assertEquals(expectedCommentLines, commentConfiguration.getAllComments().get(path));
    }

    @Test
    public void setComment_OverwritesExistingEntryForPath() {
        String path = "path";
        List<String> existingCommentLines = Arrays.asList("existingLine1", "line2");
        Map<String, List<String>> comments = Collections.singletonMap(path, existingCommentLines);
        CommentsConfiguration commentConfiguration = new CommentsConfiguration(comments);
        String[] newCommentLines = {"newLine1", "line3"};
        commentConfiguration.setComment(path, newCommentLines);
        assertEquals(newCommentLines, commentConfiguration.getAllComments().get(path));
    }

    @Test
    public void setComment_ThrowsNullPointerExceptionForNullPath() {
        CommentsConfiguration commentConfiguration = new CommentsConfiguration();
        Mockito.when(settingsHolder.getComments()).thenReturn(Collections.emptyMap());
        assertThrows(NullPointerException.class, () -> commentConfiguration.setComment(null, "line1"));
    }

    @Test
    public void setComment_ThrowsNullPointerExceptionForNullLines() {
        String path = "path";
        CommentsConfiguration commentConfiguration = new CommentsConfiguration();
        Mockito.when(settingsHolder.getComments()).thenReturn(Collections.emptyMap());
        assertThrows(NullPointerException.class, () -> commentConfiguration.setComment(path, null));
    }

    @Test
    public void getAllComments_ReturnsUnmodifiableView() {
        String path = "path";
        List<String> expectedCommentLines = Arrays.asList("line1", "line2");
        Map<String, List<String>> comments = Collections.singletonMap(path, expectedCommentLines);
        CommentsConfiguration commentConfiguration = new CommentsConfiguration(comments);
        Mockito.when(settingsHolder.getComments()).thenReturn(comments);
        assertEquals(expectedCommentLines, commentConfiguration.getAllComments().get(path));
    }
